<section id="reviews" class="section reviews"><div class="container"><div class="section-heading" data-reveal><div><p class="eyebrow"><?= site_copy('reviews_label') ?></p><h2><?= site_copy('reviews_title') ?><br><em><?= site_copy('reviews_accent') ?></em></h2></div><a class="text-link" href="<?=e(https_url($c['maps_url']))?>" target="_blank" rel="noopener"><?= site_copy('reviews_link') ?></a></div><div class="review-grid"><?php foreach($c['reviews'] as $r): ?><figure class="review" data-reveal><span class="quote-mark" aria-hidden="true">“</span><blockquote>«<?=e($r['quote'])?>»</blockquote><figcaption><span class="review-avatar"><?=e(mb_substr($r['name'],0,1))?></span><div><strong><?=e($r['name'])?></strong><?php if ($r['source'] !== ''): ?><a href="<?=e(https_url($r['source']))?>" target="_blank" rel="noopener"><?= site_copy('review_source') ?></a><?php endif; ?></div></figcaption></figure><?php endforeach; ?></div></div></section>
